import { useState, useEffect } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 3;

function renderContent(tasks: Task[] | null): JSX.Element {
  if (tasks === null) {
    return (
      <ul className="task-board-list" role="list" aria-label="Tasks">
        {Array.from({ length: SKELETON_COUNT }, (_, i) => (
          <li key={i} className="task-item task-item--skeleton">
            <span className="task-item-skeleton-text" />
          </li>
        ))}
      </ul>
    );
  }

  if (tasks.length === 0) {
    return <p className="task-board-empty">No tasks found.</p>;
  }

  return (
    <ul className="task-board-list" role="list" aria-label="Tasks">
      {tasks.map(task => (
        <li key={task.id} className="task-item">
          {task.title}
        </li>
      ))}
    </ul>
  );
}

export function TaskBoard(): JSX.Element {
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then(setTasks)
      .catch(() => setTasks([]));
  }, []);

  const count = tasks === null ? 0 : tasks.length;

  return (
    <section className="task-board" aria-label="Task board">
      <header className="task-board-header">
        <h2 className="task-board-title">Tasks</h2>
        <span className="task-board-badge" aria-label={`${count} tasks`}>
          {count}
        </span>
      </header>
      <div className="task-board-filter-bar" role="search" aria-label="Filter tasks" />
      {renderContent(tasks)}
    </section>
  );
}
